                                <button onClick={handleTestExtraction} disabled={!testFile || isLoading} className={`w-full mt-4 py-4 font-black rounded-2xl flex items-center justify-center gap-2 shadow-brand ${!testFile ? 'bg-slate-100 text-slate-300' : 'bg-primary-start text-white'}`}>{isLoading ? '...' : 'Run Extraction'}</button>
